ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS description text, ADD COLUMN IF NOT EXISTS ingredients text, ADD COLUMN IF NOT EXISTS serving_size text, ADD COLUMN IF NOT EXISTS preparation_time_minutes integer, ADD COLUMN IF NOT EXISTS allergens text[] NOT NULL DEFAULT '{}'::text[], ADD COLUMN IF NOT EXISTS dietary_tags text[] NOT NULL DEFAULT '{}'::text[];
ALTER TABLE public.menu_items ADD CONSTRAINT menu_items_price_positive CHECK (price > 0), ADD CONSTRAINT menu_items_preparation_time_positive CHECK (preparation_time_minutes IS NULL OR preparation_time_minutes > 0);
